(() => {
  'use strict';
  const $ = id => document.getElementById(id);
  const BROWSER_HTML = new Set(['html','htm','xhtml']);
  const TEXT = new Set('txt md json yaml yml csv log conf ini py sh bash zsh c cc cpp h hpp java kt go rs toml sql properties gradle dockerfile makefile gitignore env ts tsx jsx vue svelte rb php pl r'.split(' '));
  const IMAGE = new Set(['png','jpg','jpeg','gif','webp','bmp','heic']);
  const VIDEO = new Set(['mp4','mov','mkv','webm','avi']);
  const AUDIO = new Set(['mp3','wav','flac','m4a','ogg','aac']);
  const ARCHIVE = new Set(['zip','tar','gz','tgz','bz2','xz']);
  const HIDDEN = new Set(['.gitkeep','.DS_Store','.versions','.uploads','.metadata','.nginx-client-body','.nginx-client-temp']);
  const E = {app:$('app'),conn:$('conn'),body:$('body'),grid:$('grid'),table:$('table'),activityView:$('activityView'),content:$('content'),empty:$('empty'),loading:$('loading'),count:$('count'),chosen:$('chosen'),pathStatus:$('pathStatus'),address:$('address'),search:$('search'),back:$('back'),forward:$('forward'),up:$('up'),download:$('download'),move:$('move'),copy:$('copy'),archive:$('archive'),remove:$('remove'),details:$('details'),filePicker:$('filePicker'),folderPicker:$('folderPicker'),menu:$('menu'),shade:$('shade'),toasts:$('toasts'),drawer:$('drawer'),drawerTitle:$('drawerTitle'),drawerBody:$('drawerBody'),uploadPanel:$('uploadPanel'),uploadList:$('uploadList'),dropOverlay:$('dropOverlay'),quotaText:$('quotaText'),quotaFill:$('quotaFill'),sizeFilter:$('sizeFilter')};
  const S = {config:null,me:null,workspace:null,csrf:'',path:'',mode:'folder',entries:[],visible:[],selected:new Set(),focus:-1,anchor:-1,sort:'name',dir:1,query:'',kind:'all',minSize:0,history:[],hi:-1,view:localStorage.getItem('fs-view')||'list',uploads:new Map(),modalClose:null};

  function ext(name){const lower=String(name).toLowerCase();if(['dockerfile','makefile','.gitignore'].includes(lower))return lower.replace('.','');const i=lower.lastIndexOf('.');return i>0?lower.slice(i+1):''}
  function bytes(value){let n=Number(value||0);if(!Number.isFinite(n))return '—';const units=['B','KB','MB','GB','TB'];let i=0;while(n>=1024&&i<units.length-1){n/=1024;i++}return `${n.toLocaleString(undefined,{maximumFractionDigits:i?1:0})} ${units[i]}`}
  function date(value){const d=typeof value==='number'?new Date(value*1000):new Date(value);return !value||isNaN(d)?'—':d.toLocaleString()}
  function norm(path=''){path=decodeURIComponent(String(path||'').replace(/^#\/?/,'').replace(/^\/files\/?/,'').replace(/^\/+/,''));const parts=[];for(const raw of path.replace(/\\/g,'/').split('/')){if(!raw||raw==='.')continue;if(raw==='..'||raw.includes('\0'))throw Error('잘못된 경로입니다.');parts.push(raw)}return parts.length?parts.join('/')+(String(path).endsWith('/')?'/':''):''}
  function dirPath(path=''){const p=norm(path);return p&& !p.endsWith('/')?p+'/':p}
  function enc(path,folder=String(path).endsWith('/')){const p=norm(path).split('/').filter(Boolean).map(encodeURIComponent).join('/');return p+(p&&folder?'/':'')}
  function fileUrl(path,folder=String(path).endsWith('/')){return '/files/'+enc(path,folder)}
  function join(base,name,folder=false){return dirPath(base)+String(name).replace(/[\\/\0]/g,'').trim()+(folder?'/':'')}
  function joinRelative(base,relative){const parts=String(relative||'').replace(/\\/g,'/').split('/').filter(Boolean).map(part=>part.replace(/[\0]/g,'').trim()).filter(Boolean);return dirPath(base)+parts.join('/')}
  function parent(path){const parts=norm(path).split('/').filter(Boolean);parts.pop();return parts.length?parts.join('/')+'/':''}
  function basename(path){return norm(path).split('/').filter(Boolean).at(-1)||'Home'}
  function icon(item){if(item.directory)return '📁';const e=ext(item.name);if(IMAGE.has(e))return '🖼️';if(VIDEO.has(e))return '🎞️';if(AUDIO.has(e))return '🎵';if(e==='pdf')return '📕';if(ARCHIVE.has(e))return '🗜️';return TEXT.has(e)?'📄':'📃'}
  function type(item){if(item.directory)return '폴더';const e=ext(item.name);return e?e.toUpperCase()+' 파일':'파일'}
  function toast(message){const d=document.createElement('div');d.textContent=message;E.toasts.append(d);setTimeout(()=>d.remove(),4500)}
  function loading(on){E.loading.classList.toggle('show',on);if(on)E.empty.classList.remove('show')}
  async function responseJson(response){const data=await response.json().catch(()=>({}));if(!response.ok){const detail=typeof data.detail==='object'?(data.detail.message||JSON.stringify(data.detail)):(data.detail||`HTTP ${response.status}`);const error=new Error(detail);error.status=response.status;error.data=data;throw error}return data}
  async function api(url,options={}){const headers=new Headers(options.headers||{});if(S.csrf&&['POST','PUT','PATCH','DELETE'].includes(String(options.method||'GET').toUpperCase()))headers.set('X-CSRF-Token',S.csrf);if(options.body&&!(options.body instanceof Blob)&&!(options.body instanceof FormData)&&!headers.has('Content-Type'))headers.set('Content-Type','application/json');const response=await fetch(url,{cache:'no-store',...options,headers});if(response.status===204)return null;return responseJson(response)}
  async function dav(path,options={},allowed=[]){const method=String(options.method||'GET').toUpperCase(),headers=new Headers(options.headers||{});if(S.csrf&&['POST','PUT','PATCH','DELETE','MKCOL','MOVE','COPY'].includes(method))headers.set('X-CSRF-Token',S.csrf);const response=await fetch(fileUrl(path,options.directory??String(path).endsWith('/')),{cache:'no-store',...options,headers});if(!response.ok&&!allowed.includes(response.status)){const error=new Error(({401:'로그인이 필요합니다.',403:'권한이 없습니다.',404:'파일을 찾을 수 없습니다.',409:'같은 이름의 항목이 있습니다.',413:'파일이 너무 큽니다.',507:'저장 공간이 부족합니다.'})[response.status]||`HTTP ${response.status}`);error.status=response.status;throw error}return response}
  function ensureInside(path,root){const p=norm(path),r=dirPath(root);return !r||p===r.slice(0,-1)||p.startsWith(r)}
  function currentRoot(){if(S.mode==='shared')return S.workspace.shared;if(S.mode==='trash')return S.workspace.trash;return S.workspace.home}
  function canGoUp(){return S.mode==='folder'&&norm(S.path)!==norm(currentRoot())&&ensureInside(S.path,currentRoot())}

  async function bootstrap(){
    S.config=await api('/api/auth/config');
    if(S.config.mode==='private'){
      try{S.me=await api('/api/auth/me')}catch(error){if(error.status===401)return location.replace('/login?next='+encodeURIComponent(location.pathname+location.hash));throw error}
      if(S.me.user.must_change_password)return location.replace('/change-password');
      S.csrf=S.me.csrf_token;
      S.workspace=await api('/api/files/workspace');
    }else{
      S.workspace={mode:'public',username:'public',role:'public',home:'',shared:'shared/',trash:'Trash/',quota_bytes:0,usage_bytes:0,upload_chunk_bytes:8*1024*1024,can_manage_all:true};
    }
    updateQuota();bind();setView(S.view,false);await navigate(S.workspace.home,false,'home');
  }

  function updateQuota(){const {quota_bytes:quota,usage_bytes:used}=S.workspace;if(!quota){E.quotaText.textContent=`사용량 ${bytes(used)}`;E.quotaFill.style.width='0';return}E.quotaText.textContent=`${bytes(used)} / ${bytes(quota)}`;E.quotaFill.style.width=Math.min(100,used/quota*100)+'%'}
  function sideActive(view){document.querySelectorAll('.side button[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view))}
  function updateLocation(){const root=currentRoot();let display=basename(root);if(S.mode==='folder'||S.mode==='shared'||S.mode==='trash'){const rel=norm(S.path).slice(norm(root).length).split('/').filter(Boolean);display=[S.mode==='shared'?'공용 폴더':S.mode==='trash'?'휴지통':'내 파일',...rel].join(' / ')}else display=({recent:'최근 사용',favorites:'즐겨찾기',activity:'활동 기록',search:'검색 결과'})[S.mode]||'FileServer';E.address.value=display;E.search.placeholder=S.mode==='search'?'검색 결과 필터':'전체 파일 검색';E.back.disabled=S.hi<=0;E.forward.disabled=S.hi>=S.history.length-1;E.up.disabled=!canGoUp();E.pathStatus.textContent=S.mode==='folder'||S.mode==='shared'||S.mode==='trash'?'/'+norm(S.path):display}
  function setView(view,save=true){S.view=view==='grid'?'grid':'list';if(save)localStorage.setItem('fs-view',S.view);E.table.hidden=S.view!=='list'||S.mode==='activity';E.grid.hidden=S.view!=='grid'||S.mode==='activity';$('viewToggle').firstChild.textContent=S.view==='list'?'▦ ':'☷ ';render()}
  function pushHistory(state){const key=JSON.stringify(state);if(S.hi>=0&&JSON.stringify(S.history[S.hi])===key)return;S.history=S.history.slice(0,S.hi+1);S.history.push(state);S.hi=S.history.length-1}
  async function history(step){const next=S.hi+step;if(next<0||next>=S.history.length)return;S.hi=next;const state=S.history[next];await loadState(state,false)}
  async function loadState(state,add=true){if(state.mode==='recent')return loadRecent(add);if(state.mode==='favorites')return loadFavorites(add);if(state.mode==='activity')return loadActivity(add);if(state.mode==='search')return searchAll(state.query,add);return navigate(state.path,add,state.mode)}

  async function navigate(path,add=true,mode=S.mode){
    path=dirPath(path);const root=mode==='shared'?S.workspace.shared:mode==='trash'?S.workspace.trash:S.workspace.home;if(!ensureInside(path,root))path=root;
    loading(true);closeMenu();try{const response=await dav(path,{directory:true}),data=await response.json();S.mode=mode;S.path=path;S.entries=data.filter(x=>x.name&&!HIDDEN.has(x.name)).map(x=>({name:String(x.name),directory:String(x.type).toLowerCase()==='directory',size:Number(x.size||0),mtime:x.mtime||'',path:join(path,x.name,String(x.type).toLowerCase()==='directory')}));S.selected.clear();if(add)pushHistory({mode,path});sideActive(mode==='folder'?'home':mode);applyFilter();E.conn.textContent='Connected';location.hash='#/'+enc(path,true)}catch(error){E.conn.textContent='Offline';toast(error.message)}finally{loading(false);updateLocation()}}
  async function loadRecent(add=true){loading(true);try{const data=await api('/api/files/recent');S.mode='recent';S.entries=data.results;S.selected.clear();if(add)pushHistory({mode:'recent'});sideActive('recent');applyFilter()}catch(e){toast(e.message)}finally{loading(false);updateLocation()}}
  async function loadFavorites(add=true){loading(true);try{const data=await api('/api/files/favorites');S.mode='favorites';S.entries=data.results;S.selected.clear();if(add)pushHistory({mode:'favorites'});sideActive('favorites');applyFilter()}catch(e){toast(e.message)}finally{loading(false);updateLocation()}}
  async function loadActivity(add=true){loading(true);try{const data=await api('/api/files/activity');S.mode='activity';S.entries=data.activity;if(add)pushHistory({mode:'activity'});sideActive('activity');renderActivity()}catch(e){toast(e.message)}finally{loading(false);updateLocation()}}
  async function searchAll(query=S.query,add=true){query=String(query||'').trim();if(!query&&S.kind==='all'&&!S.minSize)return navigate(currentRoot(),add,S.mode==='shared'?'shared':S.mode==='trash'?'trash':'folder');loading(true);try{const params=new URLSearchParams({q:query,kind:S.kind,min_size:String(S.minSize),limit:'500'});const data=await api('/api/files/search?'+params);S.mode='search';S.entries=data.results;S.selected.clear();S.query=query;if(add)pushHistory({mode:'search',query});sideActive('');applyFilter(false)}catch(e){toast(e.message)}finally{loading(false);updateLocation()}}

  function applyFilter(local=true){const q=local?S.query.toLowerCase():'';S.visible=S.entries.filter(item=>{if(q&&!item.name.toLowerCase().includes(q))return false;if(S.minSize&&!item.directory&&item.size<S.minSize)return false;if(S.kind==='folder'&&!item.directory)return false;const e=ext(item.name);if(S.kind==='image'&&!IMAGE.has(e))return false;if(S.kind==='video'&&!VIDEO.has(e))return false;if(S.kind==='document'&&!(['pdf','doc','docx','xls','xlsx','ppt','pptx','txt','md','csv'].includes(e)))return false;if(S.kind==='archive'&&!ARCHIVE.has(e))return false;return true}).sort((a,b)=>{if(a.directory!==b.directory)return a.directory?-1:1;let result=0;if(S.sort==='name')result=a.name.localeCompare(b.name,undefined,{numeric:true,sensitivity:'base'});if(S.sort==='mtime')result=new Date(a.mtime||a.modified_at||0)-new Date(b.mtime||b.modified_at||0);if(S.sort==='type')result=type(a).localeCompare(type(b));if(S.sort==='size')result=Number(a.size||0)-Number(b.size||0);return result*S.dir||a.name.localeCompare(b.name)});render()}
  function render(){if(!E.body)return;E.activityView.hidden=true;E.table.hidden=S.view!=='list';E.grid.hidden=S.view!=='grid';E.body.replaceChildren();E.grid.replaceChildren();for(const [i,item] of S.visible.entries()){renderRow(item,i);renderTile(item,i)}E.empty.classList.toggle('show',!S.visible.length);selection();document.querySelectorAll('th[data-sort] i').forEach(i=>i.textContent='');const active=document.querySelector(`th[data-sort="${S.sort}"] i`);if(active)active.textContent=S.dir===1?'↑':'↓'}
  function renderRow(item,index){const tr=document.createElement('tr');tr.className='item-row'+(S.selected.has(item.path)?' selected':'');tr.dataset.path=item.path;const cells=[document.createElement('td'),document.createElement('td'),document.createElement('td'),document.createElement('td')];const name=document.createElement('div');name.className='name-cell';const ico=document.createElement('span');ico.className='file-icon';ico.textContent=icon(item);const text=document.createElement('span');text.textContent=item.name;name.append(ico,text);cells[0].append(name);cells[1].textContent=date(item.mtime||item.modified_at);cells[2].textContent=type(item);cells[3].textContent=item.directory?'':bytes(item.size);cells[3].className='c-size';tr.append(...cells);wireItem(tr,item,index);E.body.append(tr)}
  function renderTile(item,index){const tile=document.createElement('div');tile.className='tile'+(S.selected.has(item.path)?' selected':'');tile.dataset.path=item.path;const thumb=document.createElement('div');thumb.className='thumb';const fallback=()=>{thumb.classList.remove('has-thumbnail','pdf-thumbnail');thumb.replaceChildren(document.createTextNode(icon(item)))};const e=ext(item.name);if(!item.directory&&IMAGE.has(e)){const img=document.createElement('img');img.loading='lazy';img.decoding='async';img.src=fileUrl(item.path,false);img.alt='';img.onerror=fallback;thumb.classList.add('has-thumbnail');thumb.append(img)}else if(!item.directory&&e==='pdf'){const frame=document.createElement('iframe');frame.loading='lazy';frame.src=fileUrl(item.path,false)+'#page=1&toolbar=0&navpanes=0&scrollbar=0&view=FitH';frame.title=item.name+' 첫 페이지 썸네일';frame.tabIndex=-1;frame.onerror=fallback;thumb.classList.add('has-thumbnail','pdf-thumbnail');thumb.append(frame)}else{fallback()}const label=document.createElement('div');label.className='tile-name';label.textContent=item.name;tile.append(thumb,label);wireItem(tile,item,index);E.grid.append(tile)}
  function wireItem(element,item,index){element.onclick=e=>select(index,e);element.ondblclick=()=>openItem(item);element.oncontextmenu=e=>{e.preventDefault();if(!S.selected.has(item.path))only(index);entryMenu(e.clientX,e.clientY,item)}}
  function only(index){const item=S.visible[index];if(!item)return;S.selected=new Set([item.path]);S.focus=S.anchor=index;paint()}
  function select(index,event){const item=S.visible[index];if(!item)return;const add=event.ctrlKey||event.metaKey;if(event.shiftKey&&S.anchor>=0){if(!add)S.selected.clear();let[a,b]=[S.anchor,index].sort((x,y)=>x-y);for(;a<=b;a++)S.selected.add(S.visible[a].path)}else if(add){S.selected.has(item.path)?S.selected.delete(item.path):S.selected.add(item.path);S.anchor=index}else{S.selected=new Set([item.path]);S.anchor=index}S.focus=index;paint()}
  function paint(){document.querySelectorAll('[data-path]').forEach(el=>el.classList.toggle('selected',S.selected.has(el.dataset.path)));selection()}
  function selectedItems(){return S.visible.filter(item=>S.selected.has(item.path))}
  function selection(){const items=selectedItems(),size=items.filter(x=>!x.directory).reduce((sum,x)=>sum+Number(x.size||0),0);E.count.textContent=`${S.visible.length}개 항목`;E.chosen.textContent=items.length?`${items.length}개 선택${size?' · '+bytes(size):''}`:'';for(const button of [E.download,E.move,E.copy,E.archive,E.remove])button.disabled=!items.length;E.details.disabled=items.length!==1}
  function renderActivity(){E.table.hidden=E.grid.hidden=true;E.activityView.hidden=false;E.activityView.replaceChildren();for(const item of S.entries){const card=document.createElement('div');card.className='activity-card';const title=document.createElement('b');title.textContent=`${item.username||'시스템'} · ${item.action}`;const path=document.createElement('div');path.textContent='/'+item.path;const time=document.createElement('div');time.className='muted';time.textContent=date(item.created_at)+(item.details?' · '+item.details:'');card.append(title,path,time);E.activityView.append(card)}E.empty.classList.toggle('show',!S.entries.length)}

  async function openItem(item){if(item.directory)return navigate(item.path,true,S.mode==='shared'?'shared':S.mode==='trash'?'trash':'folder');const e=ext(item.name);if(BROWSER_HTML.has(e))return openExternal(item);if(TEXT.has(e))return showEditInfo(item);if(IMAGE.has(e)||VIDEO.has(e)||AUDIO.has(e)||e==='pdf')return preview(item);showDownloadInfo(item)}
  function downloadOne(item){const a=document.createElement('a');a.href=fileUrl(item.path,false);a.download=item.name;a.rel='noopener';a.click()}
  function openExternal(item){window.open(fileUrl(item.path,false),'_blank','noopener')}
  function linkShare(item,close){close();shareDialog(item.path)}
  function showDownloadInfo(item){const body=document.createElement('div'),info=document.createElement('div');info.className='kv';for(const [label,value] of [['이름',item.name],['유형',type(item)],['크기',bytes(item.size)],['수정한 날짜',date(item.mtime||item.modified_at)]]){const key=document.createElement('b'),text=document.createElement('span');key.textContent=label;text.textContent=value;info.append(key,text)}body.append(info);modal('파일 정보',body,[{label:'닫기'},{label:'링크 공유',action:close=>linkShare(item,close)},{label:'다운로드',kind:'primary',action:close=>{close();downloadOne(item)}}])}
  function showEditInfo(item){const body=document.createElement('div'),info=document.createElement('div');info.className='kv';for(const [label,value] of [['이름',item.name],['유형',type(item)],['크기',bytes(item.size)],['수정한 날짜',date(item.mtime||item.modified_at)]]){const key=document.createElement('b'),text=document.createElement('span');key.textContent=label;text.textContent=value;info.append(key,text)}body.append(info);const buttons=[{label:'닫기'},{label:'링크 공유',action:close=>linkShare(item,close)},{label:'다운로드',action:()=>downloadOne(item)}];if(ext(item.name)==='md')buttons.push({label:'미리보기',action:close=>{close();previewMarkdown(item)}});buttons.push({label:'수정',kind:'primary',action:close=>{close();preview(item)}});modal('파일 정보',body,buttons)}
  function safeLink(value){try{const url=new URL(value,location.href);return ['http:','https:','mailto:'].includes(url.protocol)?url.href:''}catch{return ''}}
  function markdownInline(parent,value){const pattern=/(`[^`]+`|\*\*[^*]+\*\*|~~[^~]+~~|\[[^\]]+\]\([^\s)]+\))/g;let index=0;for(const match of value.matchAll(pattern)){parent.append(document.createTextNode(value.slice(index,match.index)));const token=match[0];if(token.startsWith('`')){const code=document.createElement('code');code.textContent=token.slice(1,-1);parent.append(code)}else if(token.startsWith('**')){const strong=document.createElement('strong');strong.textContent=token.slice(2,-2);parent.append(strong)}else if(token.startsWith('~~')){const del=document.createElement('del');del.textContent=token.slice(2,-2);parent.append(del)}else{const parts=token.match(/^\[([^\]]+)\]\(([^)]+)\)$/),href=safeLink(parts?.[2]||'');if(href){const link=document.createElement('a');link.textContent=parts[1];link.href=href;link.target='_blank';link.rel='noopener noreferrer';parent.append(link)}else parent.append(document.createTextNode(token))}index=match.index+token.length}parent.append(document.createTextNode(value.slice(index)))}
  function markdownDocument(source){const article=document.createElement('article');article.className='markdown-document';const lines=String(source).replace(/\r\n?/g,'\n').split('\n');let i=0;const add=(tag,text)=>{const element=document.createElement(tag);markdownInline(element,text);article.append(element);return element};while(i<lines.length){const line=lines[i];if(!line.trim()){i++;continue}if(/^```/.test(line)){const language=line.slice(3).trim(),code=[];i++;while(i<lines.length&&!/^```/.test(lines[i]))code.push(lines[i++]);if(i<lines.length)i++;const pre=document.createElement('pre'),element=document.createElement('code');if(language)element.dataset.language=language;element.textContent=code.join('\n');pre.append(element);article.append(pre);continue}const heading=line.match(/^(#{1,6})\s+(.+)$/);if(heading){add('h'+heading[1].length,heading[2]);i++;continue}if(/^\s*([-*_])(?:\s*\1){2,}\s*$/.test(line)){article.append(document.createElement('hr'));i++;continue}if(i+1<lines.length&&line.includes('|')&&/^\s*\|?\s*:?-+:?\s*(\|\s*:?-+:?\s*)+\|?\s*$/.test(lines[i+1])){const table=document.createElement('table'),head=document.createElement('thead'),body=document.createElement('tbody'),parse=row=>row.trim().replace(/^\||\|$/g,'').split('|').map(cell=>cell.trim()),headers=parse(line),headerRow=document.createElement('tr');for(const cell of headers){const th=document.createElement('th');markdownInline(th,cell);headerRow.append(th)}head.append(headerRow);table.append(head,body);i+=2;while(i<lines.length&&lines[i].includes('|')&&lines[i].trim()){const row=document.createElement('tr');for(const cell of parse(lines[i++])){const td=document.createElement('td');markdownInline(td,cell);row.append(td)}body.append(row)}article.append(table);continue}const list=line.match(/^\s*(?:([-+*])|(\d+)\.)\s+(.+)$/);if(list){const tag=list[2]?'ol':'ul',container=document.createElement(tag);while(i<lines.length){const item=lines[i].match(/^\s*(?:([-+*])|(\d+)\.)\s+(.+)$/);if(!item||(item[2]?'ol':'ul')!==tag)break;const li=document.createElement('li');markdownInline(li,item[3]);container.append(li);i++}article.append(container);continue}if(/^>\s?/.test(line)){const quote=[];while(i<lines.length&&/^>\s?/.test(lines[i]))quote.push(lines[i++].replace(/^>\s?/,''));add('blockquote',quote.join(' '));continue}const paragraph=[line.trim()];i++;while(i<lines.length&&lines[i].trim()&&!/^(#{1,6})\s|^```|^\s*(?:[-+*]|\d+\.)\s+|^>\s?/.test(lines[i]))paragraph.push(lines[i++].trim());add('p',paragraph.join(' '))}return article}
  async function previewMarkdown(item){try{const source=await (await dav(item.path,{directory:false})).text(),body=markdownDocument(source);modal('미리보기 — '+item.name,body,[{label:'닫기'},{label:'링크 공유',action:close=>linkShare(item,close)},{label:'다운로드',action:()=>downloadOne(item)},{label:'수정',kind:'primary',action:close=>{close();preview(item)}}],true)}catch(error){toast('Markdown 미리보기 실패: '+error.message)}}
  async function shareExternal(item){if(!navigator.share)return openExternal(item);try{const response=await dav(item.path,{directory:false}),blob=await response.blob(),file=new File([blob],item.name,{type:blob.type||'application/pdf'});if(navigator.canShare&&navigator.canShare({files:[file]}))await navigator.share({files:[file],title:item.name});else openExternal(item)}catch(e){toast(e.message)}}
  async function downloadSelected(){const items=selectedItems();if(items.length===1&&!items[0].directory)return downloadOne(items[0]);const destination=join(S.workspace.home,`download-${Date.now()}.zip`);try{const data=await api('/api/files/archive',{method:'POST',body:JSON.stringify({paths:items.map(x=>x.path),destination})});const a=document.createElement('a');a.href=fileUrl(data.path,false);a.download=basename(data.path);a.click();toast('선택 항목을 ZIP으로 만들었습니다.')}catch(e){toast(e.message)}}
  async function preview(item){const wrap=document.createElement('div');wrap.className='preview';const e=ext(item.name);if(IMAGE.has(e)){const img=document.createElement('img');img.src=fileUrl(item.path,false);wrap.append(img)}else if(VIDEO.has(e)){const video=document.createElement('video');video.controls=true;video.src=fileUrl(item.path,false);wrap.append(video)}else if(AUDIO.has(e)){const audio=document.createElement('audio');audio.controls=true;audio.src=fileUrl(item.path,false);wrap.append(audio)}else if(e==='pdf'){wrap.style.background='var(--surface)';wrap.style.color='var(--text)';wrap.style.padding='24px';wrap.style.alignContent='center';const panel=document.createElement('div');panel.style.cssText='display:grid;gap:10px;justify-items:center;text-align:center';const icon=document.createElement('div');icon.style.fontSize='48px';icon.textContent='📕';const name=document.createElement('b');name.textContent=item.name;const hint=document.createElement('p');hint.className='muted';hint.textContent='브라우저 설정에 따라 PDF를 자동 미리보기하면 다운로드 확인이 뜰 수 있어 먼저 열기 방식을 선택합니다.';panel.append(icon,name,hint);wrap.append(panel);return modal('PDF 열기 — '+item.name,wrap,[{label:'닫기'},{label:'링크 공유',action:close=>linkShare(item,close)},{label:'열기',kind:'primary',action:()=>openExternal(item)},{label:'공유',action:()=>shareExternal(item)},{label:'다운로드',action:()=>downloadOne(item)}],true)}else if(TEXT.has(e)){const textarea=document.createElement('textarea');textarea.value=await (await dav(item.path,{directory:false})).text();wrap.append(textarea);return modal('편집 — '+item.name,wrap,[{label:'취소'},{label:'저장',kind:'primary',action:async close=>{try{await dav(item.path,{method:'PUT',directory:false,headers:{'Content-Type':'text/plain;charset=utf-8'},body:textarea.value});toast('저장했습니다.');close();refresh()}catch(err){toast(err.message)}}}],true)}modal('미리보기 — '+item.name,wrap,[{label:'닫기'},{label:'링크 공유',action:close=>linkShare(item,close)}],true)}

  function modal(title,body,buttons=[],wide=false){const section=document.createElement('section');section.className='modal'+(wide?' wide':'');const head=document.createElement('div');head.className='modal-head';const heading=document.createElement('b');heading.textContent=title;const closeButton=document.createElement('button');closeButton.className='icon-button';closeButton.textContent='✕';closeButton.style.marginLeft='auto';head.append(heading,closeButton);const content=document.createElement('div');content.className='modal-body';content.append(body);const foot=document.createElement('div');foot.className='modal-foot';section.append(head,content,foot);E.shade.replaceChildren(section);E.shade.classList.add('show');const close=()=>{E.shade.classList.remove('show');E.shade.replaceChildren();S.modalClose=null};S.modalClose=close;closeButton.onclick=close;for(const spec of buttons){const button=document.createElement('button');button.className='btn '+(spec.kind||'');button.textContent=spec.label;button.onclick=()=>spec.action?spec.action(close,button):close();foot.append(button)}return close}
  function formField(label,input){const row=document.createElement('div');row.className='form-row';const l=document.createElement('label');l.textContent=label;row.append(l,input);return row}
  function input(value='',type='text'){const el=document.createElement('input');el.className='input';el.type=type;el.value=value;return el}
  function promptValue(title,label,initial='',selectionEnd=null){return new Promise(resolve=>{const field=input(initial),body=document.createElement('div');body.append(formField(label,field));const close=modal(title,body,[{label:'취소',action:c=>{c();resolve(null)}},{label:'확인',kind:'primary',action:c=>{c();resolve(field.value)}}]);field.onkeydown=e=>{if(e.key==='Enter'){close();resolve(field.value)}};setTimeout(()=>{field.focus();if(selectionEnd==null)field.select();else field.setSelectionRange(0,selectionEnd)})})}
  function confirmValue(title,text,danger=false){return new Promise(resolve=>{const body=document.createElement('div');body.textContent=text;modal(title,body,[{label:'취소',action:c=>{c();resolve(false)}},{label:danger?'삭제':'확인',kind:danger?'danger':'primary',action:c=>{c();resolve(true)}}])})}

  async function createFolder(){const name=await promptValue('새 폴더','폴더 이름','새 폴더');if(!name)return;try{await dav(join(S.path,name,true),{method:'MKCOL',directory:true});toast('폴더를 만들었습니다.');refresh()}catch(e){toast(e.message)}}
  async function createFile(){const name=await promptValue('새 파일','파일 이름','새 문서.txt');if(!name)return;try{await dav(join(S.path,name),{method:'PUT',directory:false,headers:{'Content-Type':'text/plain;charset=utf-8'},body:''});toast('파일을 만들었습니다.');refresh()}catch(e){toast(e.message)}}
  async function chooseDestination(title){return new Promise(resolve=>{let current=dirPath(currentRoot());const body=document.createElement('div'),roots=document.createElement('div'),crumbs=document.createElement('div'),list=document.createElement('div'),status=document.createElement('div');roots.style.cssText='display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px';crumbs.style.cssText='display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px';list.style.cssText='min-height:260px;max-height:48vh;overflow:auto;border:1px solid var(--line);border-radius:8px';status.className='muted';status.style.marginTop='10px';body.append(roots,crumbs,list,status);const rootChoices=[['내 파일',S.workspace.home],['공용 폴더',S.workspace.shared],['휴지통',S.workspace.trash]].filter(([,path])=>path!=null);function label(path){const p=norm(path);if(p===norm(S.workspace.home))return '내 파일';if(p===norm(S.workspace.shared))return '공용 폴더';if(p===norm(S.workspace.trash))return '휴지통';const root=rootChoices.find(([,value])=>ensureInside(p,value));const rel=root?norm(p).slice(norm(root[1]).length).split('/').filter(Boolean):p.split('/').filter(Boolean);return [root?root[0]:'루트',...rel].join(' / ')}function row(text,action,muted=false){const button=document.createElement('button');button.type='button';button.textContent=text;button.style.cssText='width:100%;height:38px;border:0;border-bottom:1px solid var(--line);background:transparent;color:var(--text);text-align:left;padding:0 12px;cursor:pointer';if(muted)button.style.color='var(--muted)';button.onmouseenter=()=>button.style.background='var(--hover)';button.onmouseleave=()=>button.style.background='transparent';button.onclick=action;return button}function paintRoots(){roots.replaceChildren();for(const [name,path] of rootChoices){const button=document.createElement('button');button.className='btn';button.textContent=name;button.onclick=()=>{current=dirPath(path);load()};if(ensureInside(current,path))button.classList.add('primary');roots.append(button)}}function paintCrumbs(){crumbs.replaceChildren();const root=rootChoices.find(([,path])=>ensureInside(current,path))||rootChoices[0];const rootPath=dirPath(root[1]);const rootButton=document.createElement('button');rootButton.className='btn';rootButton.textContent=root[0];rootButton.onclick=()=>{current=rootPath;load()};crumbs.append(rootButton);const rel=norm(current).slice(norm(rootPath).length).split('/').filter(Boolean);let acc=rootPath;for(const part of rel){acc=join(acc,part,true);const target=acc,button=document.createElement('button');button.className='btn';button.textContent=part;button.onclick=()=>{current=target;load()};crumbs.append(button)}}async function load(){paintRoots();paintCrumbs();status.textContent='선택 위치: /'+norm(current);list.replaceChildren(row('불러오는 중...',()=>{},true));try{const data=await (await dav(current,{directory:true})).json();const dirs=data.filter(x=>String(x.type).toLowerCase()==='directory'&&x.name&&!HIDDEN.has(x.name)).sort((a,b)=>String(a.name).localeCompare(String(b.name),undefined,{numeric:true,sensitivity:'base'}));list.replaceChildren();if(norm(current)!==norm((rootChoices.find(([,path])=>ensureInside(current,path))||rootChoices[0])[1]))list.append(row('.. 상위 폴더',()=>{current=parent(current);load()},true));if(!dirs.length)list.append(row('하위 폴더 없음',()=>{},true));for(const item of dirs){list.append(row('📁 '+item.name,()=>{current=join(current,item.name,true);load()}))}}catch(e){list.replaceChildren(row(e.message,()=>{},true))}}const close=modal(title,body,[{label:'취소',action:c=>{c();resolve(null)}},{label:'여기로 선택',kind:'primary',action:c=>{c();resolve(dirPath(current))}}],true);const closeButton=E.shade.querySelector('.modal-head .icon-button');if(closeButton)closeButton.onclick=()=>{close();resolve(null)};load();S.modalClose=()=>{close();resolve(null)}})}
  async function moveOrCopy(copy=false){const items=selectedItems();const destination=await chooseDestination(copy?'복사할 폴더 선택':'이동할 폴더 선택');if(!destination)return;if(!copy&&items.some(item=>item.directory&&ensureInside(destination,item.path))){toast('폴더를 자기 자신 또는 하위 폴더로 이동할 수 없습니다.');return}try{await api('/api/files/'+(copy?'copy':'move'),{method:'POST',body:JSON.stringify({paths:items.map(x=>x.path),destination,overwrite:false})});toast(copy?'복사했습니다.':'이동했습니다.');refresh()}catch(e){toast(e.message)}}
  async function renameItem(item){const dot=item.directory?-1:item.name.lastIndexOf('.'),selectionEnd=dot>0?dot:item.name.length;const next=await promptValue('이름 바꾸기','새 이름',item.name,selectionEnd);if(next==null)return;const name=next.trim();if(!name||name===item.name)return;try{await api('/api/files/rename',{method:'POST',body:JSON.stringify({path:item.path,name})});toast('이름을 바꿨습니다.');refresh()}catch(e){toast(e.message)}}
  async function createArchive(){const items=selectedItems();const defaultName=join(S.path,items.length===1?items[0].name+'.zip':'선택 항목.zip');const destination=await promptValue('ZIP 만들기','저장 경로','/'+defaultName);if(!destination)return;try{await api('/api/files/archive',{method:'POST',body:JSON.stringify({paths:items.map(x=>x.path),destination})});toast('ZIP 파일을 만들었습니다.');refresh()}catch(e){toast(e.message)}}
  async function extract(item){const destination=await promptValue('압축 풀기','대상 폴더','/'+join(parent(item.path),item.name.replace(/\.(zip|tar|tgz|gz|bz2|xz)$/i,''),true));if(!destination)return;try{await api('/api/files/extract',{method:'POST',body:JSON.stringify({path:item.path,destination})});toast('압축을 풀었습니다.');refresh()}catch(e){toast(e.message)}}
  async function removeSelected(){const items=selectedItems(),permanent=S.mode==='trash';if(!await confirmValue(permanent?'영구 삭제':'휴지통으로 이동',permanent?'선택한 항목을 영구 삭제합니다. 되돌릴 수 없습니다.':'선택한 항목을 휴지통으로 이동합니다.',permanent))return;try{for(const item of items){if(permanent){await deleteTree(item.path,item.directory)}else{await api('/api/files/move',{method:'POST',body:JSON.stringify({paths:[item.path],destination:S.workspace.trash,overwrite:false})})}}toast(permanent?'영구 삭제했습니다.':'휴지통으로 이동했습니다.');refresh()}catch(e){toast(e.message)}}
  async function deleteTree(path,directory){if(!directory)return dav(path,{method:'DELETE',directory:false});const entries=await (await dav(path,{directory:true})).json();for(const entry of entries){if(HIDDEN.has(entry.name))continue;const child=join(path,entry.name,String(entry.type).toLowerCase()==='directory');await deleteTree(child,String(entry.type).toLowerCase()==='directory')}await dav(path,{method:'DELETE',directory:true})}

  async function showDetails(item){E.drawer.classList.add('show');E.drawerTitle.textContent=item.name;E.drawerBody.textContent='불러오는 중…';try{const data=await api('/api/files/metadata?path='+encodeURIComponent(item.path));E.drawerBody.replaceChildren(detailsContent(data))}catch(e){E.drawerBody.textContent=e.message}}
  function section(title){const s=document.createElement('section');s.className='drawer-section';const h=document.createElement('h3');h.textContent=title;s.append(h);return s}
  function detailsContent(data){const root=document.createDocumentFragment();const info=section('정보'),kv=document.createElement('div');kv.className='kv';for(const [key,value] of [['경로','/'+data.path],['유형',data.mime_type],['크기',bytes(data.size_bytes)],['수정',date(data.modified_at)],['SHA-256',data.sha256||'큰 파일 또는 폴더']]){const b=document.createElement('b');b.textContent=key;const v=document.createElement('span');v.textContent=value;kv.append(b,v)}info.append(kv);const favorite=document.createElement('button');favorite.className='btn';favorite.textContent=data.favorite?'★ 즐겨찾기 해제':'☆ 즐겨찾기';favorite.onclick=async()=>{await api('/api/files/favorite',{method:'POST',body:JSON.stringify({path:data.path,favorite:!data.favorite})});toast('즐겨찾기를 변경했습니다.');showDetails({name:data.name,path:data.path})};const share=document.createElement('button');share.className='btn';share.textContent='🔗 공유 링크';share.onclick=()=>shareDialog(data.path);info.append(document.createElement('br'),favorite,document.createTextNode(' '),share);root.append(info);
    const tags=section('태그'),tagWrap=document.createElement('div');tagWrap.className='tags';for(const tag of data.tags){const span=document.createElement('span');span.className='tag';span.textContent=tag;tagWrap.append(span)}const editTags=document.createElement('button');editTags.className='btn';editTags.textContent='태그 편집';editTags.style.marginTop='10px';editTags.onclick=async()=>{const value=await promptValue('태그 편집','쉼표로 구분',data.tags.join(', '));if(value==null)return;await api('/api/files/tags',{method:'POST',body:JSON.stringify({path:data.path,tags:value.split(',').map(x=>x.trim()).filter(Boolean)})});showDetails({name:data.name,path:data.path})};tags.append(tagWrap,editTags);root.append(tags);
    const versions=section(`버전 기록 (${data.versions.length})`);for(const version of data.versions){const row=document.createElement('div');row.className='version-item';const text=document.createElement('div');text.textContent=`${date(version.created_at)} · ${bytes(version.size_bytes)}`;const download=document.createElement('a');download.href='/api/files/versions/'+version.id;download.textContent='다운로드';download.style.marginRight='10px';const restore=document.createElement('button');restore.className='btn';restore.textContent='복구';restore.onclick=async()=>{if(await confirmValue('버전 복구','현재 파일을 이 버전으로 복구하시겠습니까?')){await api('/api/files/versions/restore',{method:'POST',body:JSON.stringify({version_id:version.id})});toast('버전을 복구했습니다.');refresh();showDetails({name:data.name,path:data.path})}};row.append(text,download,restore);versions.append(row)}root.append(versions);
    const comments=section('댓글');for(const comment of data.comments){const row=document.createElement('div');row.className='comment-item';row.textContent=comment.comment;const meta=document.createElement('div');meta.className='muted';meta.textContent=`${comment.username} · ${date(comment.created_at)}`;row.append(meta);comments.append(row)}const area=document.createElement('textarea');area.className='textarea';area.placeholder='댓글을 입력하세요';const add=document.createElement('button');add.className='btn primary';add.textContent='댓글 추가';add.onclick=async()=>{if(!area.value.trim())return;await api('/api/files/comments',{method:'POST',body:JSON.stringify({path:data.path,comment:area.value})});showDetails({name:data.name,path:data.path})};comments.append(area,add);root.append(comments);
    const activity=section('최근 활동');for(const entry of data.activity){const row=document.createElement('div');row.className='activity-item';row.textContent=`${entry.username||'시스템'} · ${entry.action}`;const meta=document.createElement('div');meta.className='muted';meta.textContent=date(entry.created_at)+(entry.details?' · '+entry.details:'');row.append(meta);activity.append(row)}root.append(activity);return root}
  async function shareDialog(path){const body=document.createElement('div'),password=input('','password'),days=input('7','number'),limit=input('','number');body.append(formField('비밀번호(선택)',password),formField('만료 일수',days),formField('다운로드 횟수 제한(선택)',limit));modal('공유 링크 만들기',body,[{label:'취소'},{label:'만들기',kind:'primary',action:async close=>{try{const data=await api('/api/files/shares',{method:'POST',body:JSON.stringify({path,permission:'download',password:password.value||null,expires_days:Number(days.value||7),max_downloads:limit.value?Number(limit.value):null})});const url=new URL(data.url,location.origin).href;await navigator.clipboard?.writeText(url);close();toast('공유 링크를 복사했습니다: '+url)}catch(e){toast(e.message)}}}])}
  async function manageShares(){try{const data=await api('/api/files/shares'),body=document.createElement('div'),showEmpty=()=>{if(!body.querySelector('.activity-item'))body.textContent='생성된 공유 링크가 없습니다.'};for(const share of data.shares){const row=document.createElement('div');row.className='activity-item';row.textContent=`/${share.path} · ${share.downloads}${share.max_downloads?'/'+share.max_downloads:''}회`;const meta=document.createElement('div');meta.className='muted';meta.textContent=`만료: ${date(share.expires_at)}`;const revoke=document.createElement('button');revoke.className='btn danger';revoke.textContent='해제';revoke.onclick=async()=>{revoke.disabled=true;try{await api('/api/files/shares/'+share.id,{method:'DELETE'});row.remove();showEmpty();toast('공유 링크를 해제했습니다.')}catch(error){revoke.disabled=false;toast(error.message)}};row.append(meta,revoke);body.append(row)}showEmpty();modal('공유 링크 관리',body,[{label:'닫기'}])}catch(e){toast(e.message)}}

  async function uploadFiles(files){files=[...files];if(!files.length)return;E.uploadPanel.classList.add('show');for(const file of files){const relative=file.webkitRelativePath||file.name;const target=joinRelative(S.path,relative);queueUpload(file,target)}}
  function readEntryFile(entry){return new Promise((resolve,reject)=>entry.file(resolve,reject))}
  function readEntryBatch(reader){return new Promise((resolve,reject)=>reader.readEntries(resolve,reject))}
  async function walkDroppedEntry(entry,prefix,result){const relative=prefix+entry.name;if(entry.isFile){result.files.push({file:await readEntryFile(entry),relative});return}if(!entry.isDirectory)return;result.directories.push(relative+'/');const reader=entry.createReader();for(;;){const entries=await readEntryBatch(reader);if(!entries.length)break;for(const child of entries)await walkDroppedEntry(child,relative+'/',result)}}
  async function uploadDropped(dataTransfer){const result={directories:[],files:[]},items=[...(dataTransfer.items||[])];let usedEntries=false;for(const item of items){const entry=item.webkitGetAsEntry?.();if(entry){usedEntries=true;await walkDroppedEntry(entry,'',result)}else{const file=item.kind==='file'?item.getAsFile():null;if(file)result.files.push({file,relative:file.name})}}if(!usedEntries)return uploadFiles(dataTransfer.files);for(const relative of result.directories.sort((a,b)=>a.split('/').length-b.split('/').length)){const target=dirPath(joinRelative(S.path,relative));await dav(target,{method:'MKCOL',directory:true},[405])}if(!result.files.length){toast(`${result.directories.length}개 폴더를 만들었습니다.`);return refresh()}E.uploadPanel.classList.add('show');for(const item of result.files)queueUpload(item.file,joinRelative(S.path,item.relative))}
  function queueUpload(file,target){clearTimeout(S.uploadHideTimer);const id=crypto.randomUUID(),task={id,file,target,status:'대기',received:0,total:file.size,paused:false,cancelled:false,uploadId:null};S.uploads.set(id,task);renderUpload(task);runUpload(task)}
  function hideCompletedUploads(){const tasks=[...S.uploads.values()];if(!tasks.length||tasks.some(task=>task.status!=='완료'||task.running))return;clearTimeout(S.uploadHideTimer);S.uploadHideTimer=setTimeout(()=>{const current=[...S.uploads.values()];if(current.length&&current.every(task=>task.status==='완료'&&!task.running)){E.uploadPanel.classList.remove('show');E.uploadList.replaceChildren();S.uploads.clear()}},1200)}
  function renderUpload(task){let row=E.uploadList.querySelector(`[data-upload="${task.id}"]`);if(!row){row=document.createElement('div');row.className='upload-item';row.dataset.upload=task.id;row.innerHTML='<b></b><div class="muted state-text"></div><div class="progress"><span></span></div><div class="upload-actions"><button class="pause">일시정지</button><button class="cancel">취소</button></div>';row.querySelector('b').textContent=task.file.name;row.querySelector('.pause').onclick=()=>{task.paused=!task.paused;row.querySelector('.pause').textContent=task.paused?'계속':'일시정지';if(!task.paused)runUpload(task)};row.querySelector('.cancel').onclick=async()=>{task.cancelled=true;if(task.uploadId)await api('/api/files/uploads/'+task.uploadId,{method:'DELETE'}).catch(()=>{});task.status='취소됨';renderUpload(task)};E.uploadList.append(row)}row.querySelector('.state-text').textContent=`${task.status} · ${bytes(task.received)} / ${bytes(task.total)}`;row.querySelector('.progress span').style.width=(task.total?task.received/task.total*100:100)+'%'}
  async function runUpload(task){if(task.running||task.paused||task.cancelled||task.status==='완료')return;task.running=true;try{if(!task.uploadId){task.status='준비';renderUpload(task);try{const init=await api('/api/files/uploads/init',{method:'POST',body:JSON.stringify({path:task.target,size:task.file.size,overwrite:false,relative_path:task.file.webkitRelativePath||null})});task.uploadId=init.upload_id;task.chunk=init.chunk_bytes;task.received=init.received}catch(e){if(e.status===409&&await confirmValue('파일 덮어쓰기',`${task.file.name} 파일이 존재합니다. 덮어쓰시겠습니까?`)){const init=await api('/api/files/uploads/init',{method:'POST',body:JSON.stringify({path:task.target,size:task.file.size,overwrite:true})});task.uploadId=init.upload_id;task.chunk=init.chunk_bytes}else throw e}}
      task.status='업로드 중';while(task.received<task.total&&!task.paused&&!task.cancelled){const end=Math.min(task.total,task.received+task.chunk),blob=task.file.slice(task.received,end);const result=await api('/api/files/uploads/'+task.uploadId,{method:'PUT',headers:{'Content-Type':'application/octet-stream','X-Upload-Offset':String(task.received)},body:blob});task.received=result.received;renderUpload(task)}if(task.cancelled)return;if(task.paused){task.status='일시정지';return}await api('/api/files/uploads/finish',{method:'POST',body:JSON.stringify({upload_id:task.uploadId})});task.status='완료';renderUpload(task);S.workspace=await api('/api/files/workspace');updateQuota();refresh()}catch(e){task.status='오류: '+e.message;renderUpload(task)}finally{task.running=false;hideCompletedUploads()}}

  function showMenu(x,y,items){closeMenu();for(const item of items){if(item==='-'){E.menu.append(document.createElement('hr'));continue}const button=document.createElement('button');button.textContent=item.label;button.className=item.danger?'danger':'';button.onclick=()=>{closeMenu();item.run()};E.menu.append(button)}E.menu.classList.add('show');const rect=E.menu.getBoundingClientRect();E.menu.style.left=Math.max(6,Math.min(x,innerWidth-rect.width-6))+'px';E.menu.style.top=Math.max(6,Math.min(y,innerHeight-rect.height-6))+'px'}
  function closeMenu(){E.menu.classList.remove('show');E.menu.replaceChildren()}
  function closeFloating(){if(E.shade.classList.contains('show')){S.modalClose?.();return true}if(E.menu.classList.contains('show')){closeMenu();return true}const popup=document.querySelector('.mobile-action-menu:not([hidden])');if(popup){popup.hidden=true;document.querySelectorAll('[aria-expanded="true"]').forEach(button=>button.setAttribute('aria-expanded','false'));return true}if(E.drawer.classList.contains('show')){E.drawer.classList.remove('show');return true}if(E.uploadPanel.classList.contains('show')){E.uploadPanel.classList.remove('show');return true}if(E.dropOverlay.classList.contains('show')){E.dropOverlay.classList.remove('show');return true}const sidebar=document.querySelector('.side.mobile-open');if(sidebar){sidebar.classList.remove('mobile-open');document.querySelector('.mobile-sidebar-backdrop')?.classList.remove('show');document.body.classList.remove('mobile-sidebar-open');document.getElementById('mobileSidebarToggle')?.setAttribute('aria-expanded','false');return true}return false}
  function entryMenu(x,y,item){const items=[{label:'열기',run:()=>openItem(item)},{label:'다운로드',run:downloadSelected},'-',{label:'정보 및 활동',run:()=>showDetails(item)},{label:'공유 링크',run:()=>shareDialog(item.path)},{label:'이름 바꾸기',run:()=>renameItem(item)},{label:'이동',run:()=>moveOrCopy(false)},{label:'복사',run:()=>moveOrCopy(true)}];if(item.directory)items.push({label:'ZIP으로 압축',run:createArchive});if(!item.directory&&ARCHIVE.has(ext(item.name)))items.push({label:'압축 풀기',run:()=>extract(item)});items.push('-',{label:S.mode==='trash'?'영구 삭제':'삭제',danger:S.mode==='trash',run:removeSelected});showMenu(x,y,items)}
  function refresh(){if(S.mode==='recent')return loadRecent(false);if(S.mode==='favorites')return loadFavorites(false);if(S.mode==='activity')return loadActivity(false);if(S.mode==='search')return searchAll(S.query,false);return navigate(S.path,false,S.mode)}
  function changeTheme(){const current=document.documentElement.dataset.theme||'auto',next=current==='auto'?'light':current==='light'?'dark':'auto';if(next==='auto')delete document.documentElement.dataset.theme;else document.documentElement.dataset.theme=next;localStorage.setItem('fs-theme',next);toast(`테마: ${next==='auto'?'시스템 설정':next==='light'?'라이트':'다크'}`)}

  function bind(){const theme=localStorage.getItem('fs-theme')||'auto';if(theme!=='auto')document.documentElement.dataset.theme=theme;
    document.querySelectorAll('.side button[data-view]').forEach(button=>button.onclick=()=>{const v=button.dataset.view;if(v==='home')navigate(S.workspace.home,true,'folder');if(v==='shared')navigate(S.workspace.shared,true,'shared');if(v==='trash')navigate(S.workspace.trash,true,'trash');if(v==='recent')loadRecent();if(v==='favorites')loadFavorites();if(v==='activity')loadActivity()});
    document.querySelectorAll('th[data-sort]').forEach(th=>th.onclick=()=>{const key=th.dataset.sort;if(S.sort===key)S.dir*=-1;else{S.sort=key;S.dir=1}applyFilter()});document.querySelectorAll('.chip').forEach(chip=>chip.onclick=()=>{document.querySelectorAll('.chip').forEach(c=>c.classList.remove('active'));chip.classList.add('active');S.kind=chip.dataset.kind;if(E.search.value.trim())searchAll(E.search.value);else applyFilter()});
    $('newFolder').onclick=createFolder;$('newFile').onclick=createFile;$('uploadFiles').onclick=()=>E.filePicker.click();$('uploadFolder').onclick=()=>E.folderPicker.click();E.filePicker.onchange=()=>{uploadFiles(E.filePicker.files);E.filePicker.value=''};E.folderPicker.onchange=()=>{uploadFiles(E.folderPicker.files);E.folderPicker.value=''};E.download.onclick=downloadSelected;E.move.onclick=()=>moveOrCopy(false);E.copy.onclick=()=>moveOrCopy(true);E.archive.onclick=createArchive;E.remove.onclick=removeSelected;E.details.onclick=()=>{const[item]=selectedItems();if(item)showDetails(item)};$('viewToggle').onclick=()=>setView(S.view==='list'?'grid':'list');$('refresh').onclick=refresh;E.back.onclick=()=>history(-1);E.forward.onclick=()=>history(1);E.up.onclick=()=>canGoUp()&&navigate(parent(S.path),true,S.mode);$('sharesButton').onclick=manageShares;$('themeButton').onclick=changeTheme;E.closeDrawer.onclick=()=>E.drawer.classList.remove('show');$('closeUploads').onclick=()=>E.uploadPanel.classList.remove('show');E.sizeFilter.onchange=()=>{S.minSize=Number(E.sizeFilter.value);E.search.value.trim()?searchAll(E.search.value):applyFilter()};
    let timer;E.search.oninput=()=>{clearTimeout(timer);S.query=E.search.value;timer=setTimeout(()=>searchAll(S.query),300)};E.address.onfocus=()=>{E.address.value='/'+norm(S.path);E.address.select()};E.address.onblur=updateLocation;E.address.onkeydown=e=>{if(e.key==='Enter'){navigate(E.address.value,true,S.mode);E.address.blur()}if(e.key==='Escape'){updateLocation();E.address.blur()}};E.content.onclick=e=>{if(!e.target.closest('[data-path]')){S.selected.clear();paint()}};E.content.oncontextmenu=e=>{if(!e.target.closest('[data-path]')){e.preventDefault();showMenu(e.clientX,e.clientY,[{label:'새 폴더',run:createFolder},{label:'새 파일',run:createFile},{label:'업로드',run:()=>E.filePicker.click()},'-',{label:'새로고침',run:refresh}])}};document.onclick=e=>{if(!e.target.closest('#menu'))closeMenu()};document.addEventListener('scroll',closeMenu,true);addEventListener('resize',closeMenu);
    document.addEventListener('keydown',e=>{if(e.key!=='Escape'||!closeFloating())return;e.preventDefault();e.stopImmediatePropagation()},true);document.onkeydown=e=>{if(e.target.matches('input,textarea,select'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='a'){e.preventDefault();S.selected=new Set(S.visible.map(x=>x.path));paint()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='f'){e.preventDefault();E.search.focus()}if(e.key==='Delete'&&selectedItems().length){e.preventDefault();removeSelected()}if(e.key==='Enter'&&selectedItems().length===1)openItem(selectedItems()[0]);if(e.key==='Backspace'&&canGoUp()){e.preventDefault();navigate(parent(S.path),true,S.mode)}};
    let depth=0;const hasFiles=e=>Array.from(e.dataTransfer?.types||[]).includes('Files');document.ondragenter=e=>{if(!hasFiles(e))return;e.preventDefault();depth++;E.dropOverlay.classList.add('show')};document.ondragover=e=>{if(!hasFiles(e))return;e.preventDefault();e.dataTransfer.dropEffect='copy'};document.ondragleave=e=>{if(!hasFiles(e))return;if(--depth<=0){depth=0;E.dropOverlay.classList.remove('show')}};document.ondrop=async e=>{if(!hasFiles(e))return;e.preventDefault();depth=0;E.dropOverlay.classList.remove('show');try{await uploadDropped(e.dataTransfer)}catch(error){toast('폴더 업로드 실패: '+error.message)}};
  }

  bootstrap().catch(error=>{console.error(error);toast(error.message);E.conn.textContent='Offline'});
})();
